/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

const fs = require('fs');

// Validators
const VALID_CHARS = /^[A-Za-z0-9_.\/:_-]+$/;

function isValidName(name) {
  return VALID_CHARS.test(name);
}

function isValidInteger(str, min) {
  // Must be non-negative decimal without leading zeros (except for "0" itself)
  if (!/^\d+$/.test(str)) return false;
  if (str.length > 1 && str[0] === '0') return false;
  const num = parseInt(str, 10);
  return num >= min;
}

// Token bucket implementation
class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity;
    this.refill = refill;
    this.per = per;
    this.states = new Map(); // key -> { tokens, lastTick }
  }

  advance(key, tick) {
    if (!this.states.has(key)) {
      this.states.set(key, { tokens: this.capacity, lastTick: tick });
    } else {
      const state = this.states.get(key);
      const ticksPassed = tick - state.lastTick;
      const tokensAdded = (this.refill * ticksPassed) / this.per;
      state.tokens = Math.min(this.capacity, state.tokens + tokensAdded);
      state.lastTick = tick;
    }
  }

  allow(key) {
    const state = this.states.get(key);
    return state && state.tokens >= 1;
  }

  record(key) {
    const state = this.states.get(key);
    if (state) {
      state.tokens -= 1;
    }
  }
}

// Sliding window implementation
class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit;
    this.span = span;
    this.windows = new Map(); // key -> array of ticks
  }

  advance(key, tick) {
    if (!this.windows.has(key)) {
      this.windows.set(key, []);
    }
    const ticks = this.windows.get(key);
    // Remove ticks outside the window: forget ticks at or before tick - span
    while (ticks.length > 0 && ticks[0] <= tick - this.span) {
      ticks.shift();
    }
  }

  allow(key) {
    const ticks = this.windows.get(key);
    if (!ticks) return true;
    return ticks.length < this.limit;
  }

  record(key, tick) {
    const ticks = this.windows.get(key);
    if (ticks) {
      ticks.push(tick);
    }
  }
}

function main() {
  const mode = process.argv[2];

  if (!mode || !['replay', 'summary'].includes(mode)) {
    process.stderr.write('error: usage: cli.js replay|summary\n');
    process.exit(2);
  }

  // Read from stdin
  let input;
  try {
    input = fs.readFileSync(0, 'utf-8');
  } catch (err) {
    process.stderr.write('error: failed to read stdin\n');
    process.exit(2);
  }

  // Split on newlines and drop empty tail
  const rawLines = input.split('\n');
  // If the input ends with a newline, the last element will be empty; drop it
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') {
    rawLines.pop();
  }

  // Parse
  const buckets = new Map();
  const windows = new Map();
  const routes = [];
  const events = [];
  let seenFirstEvent = false;
  let lastTick = -1;

  function error(lineNum, reason) {
    process.stderr.write(`error: line ${lineNum}: ${reason}\n`);
    process.exit(2);
  }

  let lineNum = 0;
  for (const rawLine of rawLines) {
    lineNum++;

    // Trim and process
    let line = rawLine.trim();

    // Skip empty lines and comments
    if (!line || line.startsWith('#')) continue;

    // Split on runs of whitespace
    const parts = line.split(/\s+/);
    const directive = parts[0];

    if (directive === 'bucket') {
      if (seenFirstEvent) error(lineNum, 'declarations must come before the first event');
      if (parts.length !== 5) error(lineNum, 'expected bucket <name> <capacity> <refill> <per>');

      const name = parts[1];
      const capacityStr = parts[2];
      const refillStr = parts[3];
      const perStr = parts[4];

      if (!isValidName(name)) error(lineNum, `invalid policy name ${name}`);
      if (!isValidInteger(capacityStr, 1)) error(lineNum, 'capacity must be an integer of at least 1');
      if (!isValidInteger(refillStr, 0)) error(lineNum, 'refill must be an integer of at least 0');
      if (!isValidInteger(perStr, 1)) error(lineNum, 'per must be an integer of at least 1');

      if (buckets.has(name) || windows.has(name)) error(lineNum, `policy ${name} is declared twice`);

      const capacity = parseInt(capacityStr, 10);
      const refill = parseInt(refillStr, 10);
      const per = parseInt(perStr, 10);

      buckets.set(name, new TokenBucket(capacity, refill, per));

    } else if (directive === 'window') {
      if (seenFirstEvent) error(lineNum, 'declarations must come before the first event');
      if (parts.length !== 4) error(lineNum, 'expected window <name> <limit> <span>');

      const name = parts[1];
      const limitStr = parts[2];
      const spanStr = parts[3];

      if (!isValidName(name)) error(lineNum, `invalid policy name ${name}`);
      if (!isValidInteger(limitStr, 0)) error(lineNum, 'limit must be an integer of at least 0');
      if (!isValidInteger(spanStr, 1)) error(lineNum, 'span must be an integer of at least 1');

      if (buckets.has(name) || windows.has(name)) error(lineNum, `policy ${name} is declared twice`);

      const limit = parseInt(limitStr, 10);
      const span = parseInt(spanStr, 10);

      windows.set(name, new SlidingWindow(limit, span));

    } else if (directive === 'route') {
      if (seenFirstEvent) error(lineNum, 'declarations must come before the first event');
      if (parts.length < 3) error(lineNum, 'expected route <prefix> <policy>...');

      const prefix = parts[1];
      const policies = parts.slice(2);

      if (!isValidName(prefix)) error(lineNum, `invalid route prefix ${prefix}`);

      // Check all policies exist
      for (const policy of policies) {
        if (!buckets.has(policy) && !windows.has(policy)) {
          error(lineNum, `unknown policy ${policy}`);
        }
      }

      // Check prefix not duplicated
      for (const route of routes) {
        if (route.prefix === prefix) error(lineNum, `prefix ${prefix} is routed twice`);
      }

      routes.push({ prefix, policies });

    } else if (directive === 'event') {
      seenFirstEvent = true;
      if (parts.length !== 3) error(lineNum, 'expected event <tick> <key>');

      const tickStr = parts[1];
      const key = parts[2];

      if (!isValidInteger(tickStr, 0)) error(lineNum, 'tick must be an integer of at least 0');
      if (!isValidName(key)) error(lineNum, `invalid key ${key}`);

      const tick = parseInt(tickStr, 10);
      if (tick < lastTick) error(lineNum, `tick ${tick} is before tick ${lastTick}`);
      lastTick = tick;

      events.push({ tick, key });

    } else {
      error(lineNum, `unknown directive ${directive}`);
    }
  }

  // Process events
  const results = [];
  const keyStats = new Map();

  for (const event of events) {
    // Find matching route (longest matching prefix)
    let matchedRoute = null;
    let longestPrefix = '';
    for (const route of routes) {
      if (event.key.startsWith(route.prefix) && route.prefix.length > longestPrefix.length) {
        matchedRoute = route;
        longestPrefix = route.prefix;
      }
    }

    // Process policies
    let allowed = true;
    let deniedBy = null;

    if (matchedRoute) {
      // Advance all policies to the current tick
      for (const policyName of matchedRoute.policies) {
        const bucket = buckets.get(policyName);
        const window = windows.get(policyName);
        if (bucket) bucket.advance(event.key, event.tick);
        if (window) window.advance(event.key, event.tick);
      }

      // Check if all policies allow
      for (const policyName of matchedRoute.policies) {
        const bucket = buckets.get(policyName);
        const window = windows.get(policyName);
        let allows = true;

        if (bucket) allows = allows && bucket.allow(event.key);
        if (window) allows = allows && window.allow(event.key);

        if (!allows) {
          allowed = false;
          deniedBy = policyName;
          break;
        }
      }

      // Record if all allowed
      if (allowed) {
        for (const policyName of matchedRoute.policies) {
          const bucket = buckets.get(policyName);
          const window = windows.get(policyName);
          if (bucket) bucket.record(event.key);
          if (window) window.record(event.key, event.tick);
        }
      }
    }

    // Track stats
    if (!keyStats.has(event.key)) {
      keyStats.set(event.key, { allowed: 0, denied: 0 });
    }
    const stats = keyStats.get(event.key);
    if (allowed) {
      stats.allowed++;
    } else {
      stats.denied++;
    }

    results.push({ tick: event.tick, key: event.key, allowed, deniedBy });
  }

  // Output
  if (mode === 'replay') {
    for (const result of results) {
      if (result.allowed) {
        console.log(`${result.tick} ${result.key} allow`);
      } else {
        console.log(`${result.tick} ${result.key} deny ${result.deniedBy}`);
      }
    }
  } else if (mode === 'summary') {
    const sortedKeys = Array.from(keyStats.keys()).sort();
    let totalAllowed = 0;
    let totalDenied = 0;

    for (const key of sortedKeys) {
      const stats = keyStats.get(key);
      totalAllowed += stats.allowed;
      totalDenied += stats.denied;
      console.log(`${key} allowed=${stats.allowed} denied=${stats.denied}`);
    }

    console.log(`total allowed=${totalAllowed} denied=${totalDenied}`);
  }

  process.exit(0);
}

main();
