      if (seenFirstEvent) error(lineNum, 'declarations must come before the first event');
      if (parts.length < 3) error(lineNum, 'expected route <prefix> <policy>...');

      const prefix = parts[1];
      const policies = parts.slice(2);

      if (!isValidName(prefix)) error(lineNum, `invalid route prefix ${prefix}`);

