      if (!isValidName(key)) error(lineNum, `invalid key ${key}`);

      const tick = parseInt(tickStr, 10);
      if (tick < lastTick) error(lineNum, `tick ${tick} is before tick ${lastTick}`);
      lastTick = tick;

      events.push({ tick, key });

