  const results = [];
  const keyStats = new Map();

  for (const event of events) {
    // Find matching route (longest matching prefix)
    let matchedRoute = null;
    let longestPrefix = '';
    for (const route of routes) {
      if (event.key.startsWith(route.prefix) && route.prefix.length > longestPrefix.length) {
        matchedRoute = route;
        longestPrefix = route.prefix;
      }
    }

    // Process policies
    let allowed = true;
    let deniedBy = null;

    if (matchedRoute) {
      // Advance all policies to the current tick
      for (const policyName of matchedRoute.policies) {
        const bucket = buckets.get(policyName);
        const window = windows.get(policyName);
        if (bucket) bucket.advance(event.key, event.tick);
        if (window) window.advance(event.key, event.tick);
      }

      // Check if all policies allow
      for (const policyName of matchedRoute.policies) {
        const bucket = buckets.get(policyName);
        const window = windows.get(policyName);
        let allows = true;

        if (bucket) allows = allows && bucket.allow(event.key);
        if (window) allows = allows && window.allow(event.key);

        if (!allows) {
          allowed = false;
          deniedBy = policyName;
          break;
        }
      }

      // Record if all allowed
      if (allowed) {
        for (const policyName of matchedRoute.policies) {
          const bucket = buckets.get(policyName);
          const window = windows.get(policyName);
          if (bucket) bucket.record(event.key);
          if (window) window.record(event.key, event.tick);
        }
      }
    }

    // Track stats
    if (!keyStats.has(event.key)) {
      keyStats.set(event.key, { allowed: 0, denied: 0 });
    }
    const stats = keyStats.get(event.key);
    if (allowed) {
      stats.allowed++;
    } else {
      stats.denied++;
    }

    results.push({ tick: event.tick, key: event.key, allowed, deniedBy });
  }

